// Manual AWS SigV4 signing for Cloudflare R2
const crypto = require('crypto');
const now = new Date();

// Format dates for AWS signature
const amzDate = now.toISOString().replace(/[\-:]/g, '').split('.')[0] + 'Z';
const dateStamp = amzDate.split('T')[0];

// Get image buffer
const imageBuffer = $input.first().binary.data.data;
const fileKey = `receipts/${$json.user_id}/${$json.filename}`;
const bucket = 'receiptai-images';
const endpoint = 'https://e21ca487c714259a0c1d0ff82c8e8ff6f.r2.cloudflarestorage.com';
const uploadUrl = `${endpoint}/${bucket}/${fileKey}`;

// Calculate SHA256 of payload
const payloadHash = crypto.createHash('sha256').update(imageBuffer).digest('hex');

// Create canonical request
const canonicalRequest = [
  'PUT',
  `/${bucket}/${fileKey}`,
  '',
  `host:e21ca487c714259a0c1d0ff82c8e8ff6f.r2.cloudflarestorage.com`,
  `x-amz-acl:public-read`,
  `x-amz-content-sha256:${payloadHash}`,
  `x-amz-date:${amzDate}`,
  '',
  'host;x-amz-acl;x-amz-content-sha256;x-amz-date',
  payloadHash
].join('\n');

// Create string to sign
const algorithm = 'AWS4-HMAC-SHA256';
const credentialScope = `${dateStamp}/auto/s3/aws4_request`;
const stringToSign = [
  algorithm,
  amzDate,
  credentialScope,
  crypto.createHash('sha256').update(canonicalRequest).digest('hex')
].join('\n');

// Calculate signature
const hmac = (key, msg) => crypto.createHmac('sha256', key).update(msg).digest();
const getSignatureKey = (key, dateStamp, regionName, serviceName) => {
  const kDate = hmac(Buffer.from('AWS4' + key), dateStamp);
  const kRegion = hmac(kDate, regionName);
  const kService = hmac(kRegion, serviceName);
  return hmac(kService, 'aws4_request');
};

const accessKeyId = $env.R2_ACCESS_KEY_ID;
const secretAccessKey = $env.R2_SECRET_ACCESS_KEY;
const signingKey = getSignatureKey(secretAccessKey, dateStamp, 'auto', 's3');
const signature = hmac(signingKey, stringToSign).toString('hex');

// Return signed request details
return [{
  json: {
    uploadUrl,
    fileKey,
    headers: {
      'Content-Type': 'image/jpeg',
      'x-amz-acl': 'public-read',
      'x-amz-content-sha256': payloadHash,
      'x-amz-date': amzDate,
      'Authorization': `${algorithm} Credential=${accessKeyId}/${credentialScope}, SignedHeaders=host;x-amz-acl;x-amz-content-sha256;x-amz-date, Signature=${signature}`
    },
    body: imageBuffer,
    publicUrl: `https://receiptimages.daeit.com.sg/${fileKey}`
  }
}];
